oa::Matrix oa::MultiHeadAttention::forwardStandard(
	const oa::Matrix& inInput, const oa::Matrix& inAdditiveMask) {
	OA_REQUIRE_MSG(inInput.rank() == 2 && inInput.size(1) == dModel_
		&& seqLen_ > 0 && inInput.size(0) % seqLen_ == 0,
		"MultiHeadAttention expects [B*S,D] with a configured sequence length");
	const oa::I32 batch = static_cast<oa::I32>(inInput.size(0) / seqLen_);
	const oa::I64 scoreRows = static_cast<oa::I64>(batch) * numHeads_ * seqLen_;
	OA_REQUIRE_MSG(inAdditiveMask.rank() == 2
		&& inAdditiveMask.size(0) == scoreRows
		&& inAdditiveMask.size(1) == seqLen_,
		"MultiHeadAttention additive mask must be [B*H*S,S]");

	auto qkv = projectQkv(inInput);
	auto q = oa::FnMatrix::splitHeads(qkv[0], batch, seqLen_, numHeads_);
	auto k = oa::FnMatrix::splitHeads(qkv[1], batch, seqLen_, numHeads_);
	auto v = oa::FnMatrix::splitHeads(qkv[2], batch, seqLen_, numHeads_);
	auto scores = oa::FnMatrix::bmmNt(q, k);
	auto attn = oa::FnMatrix::softmaxScaledMasked(
		scores.reshape(MatrixShape{scoreRows, seqLen_}), inAdditiveMask,
		1.0F / oa::sqrt(static_cast<oa::F32>(headDim_)));
	if (isTraining() && dropoutP_ > 0.0F) {
		attn = oa::FnMatrix::dropout(attn, dropoutP_);
	}
	auto context = oa::FnMatrix::bmm(
		attn.reshape(MatrixShape{static_cast<oa::I64>(batch) * numHeads_, seqLen_, seqLen_}), v);
	auto merged = oa::FnMatrix::mergeHeads(context, batch, seqLen_, numHeads_);
	return outProj_->forward(merged);
}

oa::Matrix oa::MultiHeadAttention::forwardFlash(const oa::Matrix& inInput) {
	OA_REQUIRE_MSG(inInput.rank() == 2 && inInput.size(1) == dModel_
		&& seqLen_ > 0 && inInput.size(0) % seqLen_ == 0,
		"MultiHeadAttention expects [B*S,D] with a configured sequence length");
	const oa::I32 batch = static_cast<oa::I32>(inInput.size(0) / seqLen_);
	auto qkv = projectQkv(inInput);
	auto q = oa::FnMatrix::splitHeads(qkv[0], batch, seqLen_, numHeads_);
	auto k = oa::FnMatrix::splitHeads(qkv[1], batch, seqLen_, numHeads_);
	auto v = oa::FnMatrix::splitHeads(qkv[2], batch, seqLen_, numHeads_);
	auto context = oa::FnMatrix::flashAttentionCausal(
		q, k, v, 1.0F / oa::sqrt(static_cast<oa::F32>(headDim_)));
	auto merged = oa::FnMatrix::mergeHeads(context, batch, seqLen_, numHeads_);
	lastBackend_ = oa::AttentionBackend::Flash;
	return outProj_->forward(merged);
}

oa::Matrix oa::MultiHeadAttention::forward(const oa::Matrix& inInput) {
OA_REQUIRE_MSG(seqLen_ > 0, "MultiHeadAttention requires setSeqLen before forward");
const bool requestFlash = mode_ == oa::AttentionMode::Causal &&
	backend_ == oa::AttentionBackend::Flash;
if (requestFlash && canUseFlash(inInput)) return forwardFlash(inInput);
OA_REQUIRE_MSG(backend_ != oa::AttentionBackend::Flash,
	"FlashAttention requires causal mode, FP32, dropout=0 and sequence length <= 1024");
lastBackend_ = oa::AttentionBackend::Standard;
return forwardStandard(inInput, attentionMask(static_cast<oa::I32>(inInput.size(0) / seqLen_)));
}
